def fib_fast_doubling(n):
    def go(k):
        if k == 0:
            return (0, 1)
        a, b = go(k >> 1)
        c = a * (2 * b - a)
        d = a * a + b * b
        return (d, c + d) if k & 1 else (c, d)
    return go(n)[0]

print([fib_fast_doubling(n) for n in range(10)], fib_fast_doubling(100))

def mat_mult(a, b):
    return [
        [a[0][0] * b[0][0] + a[0][1] * b[1][0], a[0][0] * b[0][1] + a[0][1] * b[1][1]],
        [a[1][0] * b[0][0] + a[1][1] * b[1][0], a[1][0] * b[0][1] + a[1][1] * b[1][1]],
    ]

def fib_matrix(n):
    result = [[1, 0], [0, 1]]
    base = [[1, 1], [1, 0]]
    while n:
        if n & 1:
            result = mat_mult(result, base)
        base = mat_mult(base, base)
        n >>= 1
    return result[0][1]

print([fib_matrix(n) for n in range(10)], fib_matrix(50))

def fib_naive(n):
    if n < 2:
        return n
    return fib_naive(n - 1) + fib_naive(n - 2)

from functools import lru_cache

@lru_cache(maxsize=None)
def fib_memo(n):
    if n < 2:
        return n
    return fib_memo(n - 1) + fib_memo(n - 2)

print(fib_naive(15), fib_memo(80))

def flatten_eager(xs):
    out = []
    for x in xs:
        if isinstance(x, list):
            out.extend(flatten_eager(x))
        else:
            out.append(x)
    return out

def flatten_lazy(xs):
    for x in xs:
        if isinstance(x, list):
            yield from flatten_lazy(x)
        else:
            yield x

nested = [1, [2, [3, 4], 5], [[6]]]
print(flatten_eager(nested), list(flatten_lazy(nested)))

